import { Component, OnInit } from '@angular/core';
import {HomeService} from '../home.service'
import {ActivatedRoute,Router} from '@angular/router'
import {ModalController} from '@ionic/angular'
import {CollectordetailsPage} from '../collectordetails/collectordetails.page'

@Component({
  selector: 'app-collector',
  templateUrl: './collector.page.html',
  styleUrls: ['./collector.page.scss'],
})
export class CollectorPage implements OnInit {
  collectorstates=[];
  collect ={};
  constructor(private user:HomeService,private route:ActivatedRoute,private router:Router,private modalctrl:ModalController) {
    this.user.collector().subscribe(data =>{
      this.collectorstates=data as any;
    })
   }

  ngOnInit() {
  }
 async btnClicked(collect){
   const modal= await this.modalctrl.create({
    component: CollectordetailsPage,
    componentProps:{collector:collect}
    });
  
await modal.present();
 
}
}
